];

function extractRows() {
  const t = document.querySelectorAll('#show_search_result table')[1];
  if (!t) return [];
  const rows = [...t.rows].slice(1).map(r => [...r.cells].map(c=>c.innerText.trim().replace(/\s+/g,' ')));
  return rows;
}

function getPagerInfo() {
  const txt = document.getElementById('show_search_result').innerText;
  const m = txt.match(/總筆數\s*共(\d+)筆.*?第\s*(\d+)\s*頁\/共\s*(\d+)\s*頁/s);
  if (!m) return {total:0, page:1, pages:1};
  return {total:+m[1], page:+m[2], pages:+m[3]};
}

async function runWindow(start, end) {
  $('#dp1786957988828').val(start);
  $('#dp1786957988829').val(end);
  search_invoice_info.send_search_invoice('1');
  await new Promise(r=>setTimeout(r, 1800));
  let info = getPagerInfo();
  let collected = extractRows();
  let page = 1;
  while (page < info.pages) {
    page++;
    search_invoice_info.send_search_invoice(String(page));
    await new Promise(r=>setTimeout(r, 1500));
    collected = collected.concat(extractRows());
    info = getPagerInfo();
  }
  return {start, end, total: info.total, gotRows: collected.length, rows: collected};
}

const results = [];
for (const [s,e] of window.__windows) {
  const r = await runWindow(s,e);
  results.push(r);
}
window.__allInvoices = results;
JSON.stringify(results.map(r=>({start:r.start,end:r.end,total:r.total,gotRows:r.gotRows})));

window.__allInvoices = window.__allInvoices || [];

